function runStory(s, roleId) {
  const t = wTier(); const place = esc(capName(G.loc));
  const extra = (typeof ROLE_OPTS !== 'undefined' && ROLE_OPTS[s[1]] && hasRole(ROLE_OPTS[s[1]][0])) ? [ROLE_OPTS[s[1]][1]] : [];
  const opts = [...s[3], ...extra];
  const gates = gateSet(opts.map(o => ({ lab: o[0], attr: o[1] })), t);
  const L = opts.map((o, gi) => { const [lab, attr, tags, okT, koT, okFx, koFx, kar] = o; const dc = 11 + 2 * t;
    return C(lab, () => {
      const r = check(attr, dc, tags); if (kar) addKarma(kar); const ok = r.ok; const rw = Object.assign({}, ok ? okFx : koFx); if (ok && rw.xp) rw.xp += 4 * t;
      show({ chainTitle: s[1], kicker: s[0], title: ok ? 'Réussi' : 'Raté', text: [ok ? okT : koT, checkLine(r)], fx: fx(rw), choices: [C('Continuer', hub)] });
    }, { odds: [attr, dc, tags], ic: kar > 0 ? '🤝' : kar < 0 ? '😈' : '🎲', req: gates.has(gi) ? { attr: { [attr]: gates.get(gi) } } : undefined, sub: (extra.includes(o) ? '🎭 Rôle · ' : '') + (gates.has(gi) ? `🔑 ${AT[attr].short} ${gates.get(gi)}` : '') });
  });
  { const qa = questAbility(); const m = qa && questReady(qa) ? opts.find(o => questFits(qa, o[2])) : null;
    if (m) L.push(C(`✨ ${qa.q.n}`, () => { questUse(); if (m[7]) addKarma(m[7]); const rw = Object.assign({}, m[5]); if (rw.xp) rw.xp += 4 * t; show({ chainTitle: s[1], kicker: s[0], title: 'Pouvoir utilisé', text: [qa.q.line, `✨ ${qa.q.n} (${qa.power}) · 2⚡`], fx: fx(rw), choices: [C('Continuer', hub)] }); }, { ic: '✨', cls: 'safe', sub: `${qa.q.d} · réussite assurée · 2⚡ · 1×/destination` })); }
  L.push(C('Passer ton chemin', hub, { cls: 'back' }));
  show({ kicker: s[0] + ' · ' + capName(G.loc).toUpperCase(), title: s[1], text: [s[2](place)], choices: L });
}
function storyCard() {
  const f = G.pc.flags; const seen = f.storySeen = f.storySeen || [];
  const loc = Object.keys(LOCAL_STORIES).filter(k => F[k] && F[k].hq === G.loc);
  if (loc.length && chance(0.6)) {
    const lk = f.storyLoc = f.storyLoc || []; const k = pick(loc); const arr = LOCAL_STORIES[k]; const id = k + ':' + rint(0, arr.length - 1);
    if (!lk.includes(id)) { lk.push(id); return runStory(arr[+id.split(':')[1]]); }
  }
  let ids = STORIES.map((_, i) => i).filter(i => !seen.includes(i) && !uniqSkip('stories', i)); if (!ids.length) { f.storySeen = []; ids = STORIES.map((_, i) => i); }
  const i = pick(ids); seen.push(i); if (seen.length > STORIES.length - 4) seen.shift(); runStory(STORIES[i]);
}
function storyPool(pool) { pool.push({ w: 30, f: storyCard }); if (G.pc.roles.length) pool.push({ w: 14 + 6 * G.pc.roles.length, f: roleStoryCard }); }

